std::uint32_t sext(std::uint32_t value, unsigned bits) {
    const unsigned shift = 32u - bits;
    return static_cast<std::uint32_t>(static_cast<std::int32_t>(value << shift) >> shift);
}
std::uint32_t sra(std::uint32_t value, unsigned bits) { return static_cast<std::uint32_t>(static_cast<std::int32_t>(value) >> bits); }
// `ins value, source, position, 1`: the bit at `position` replaced by source's lowest bit.
constexpr std::uint32_t ins(std::uint32_t value, std::uint32_t source, unsigned position) {
    return (value & ~(1u << position)) | ((source & 1u) << position);
}
// The `lui` half of an address whose `lo` is added as a signed 16-bit immediate.
constexpr std::uint32_t high_half(std::uint32_t address) { return (address + 0x8000u) & 0xFFFF0000u; }
std::uint32_t bits_of(float value) { return std::bit_cast<std::uint32_t>(value); }
void jump(psprecomp::AllegrexContext &ctx, std::uint32_t target) { ctx.pc = target; }
// Allegrex `trunc.w.s`: toward zero; NaN and out of range give 0x7FFFFFFF.
std::int32_t trunc_w_s(float value) {
    if (!(value >= -2147483648.0f && value < 2147483648.0f)) return 0x7FFFFFFF;
    return static_cast<std::int32_t>(value);
}
// `div`: lo the quotient, hi the remainder, both toward zero; INT_MIN / -1 gives INT_MIN and 0 (no host trap), and a
// zero divisor leaves hi = the dividend and lo = -1 (dividend >= 0) or 1, as Allegrex does.
void divide(psprecomp::AllegrexContext &ctx, std::uint32_t dividend, std::uint32_t divisor) {
    const auto a = static_cast<std::int32_t>(dividend);
    const auto b = static_cast<std::int32_t>(divisor);
    if (b == 0) { ctx.lo = a >= 0 ? 0xFFFFFFFFu : 1u; ctx.hi = dividend; return; }
    if (b == -1) { ctx.lo = static_cast<std::uint32_t>(0u - dividend); ctx.hi = 0u; return; }
    ctx.lo = static_cast<std::uint32_t>(a / b);
    ctx.hi = static_cast<std::uint32_t>(a % b);
}
// A `jal` with the registers as they stand (the caller's frame already open); v0 / v1 / f0 back as the callee left them.
void call_here(psprecomp::Runtime &rt, psprecomp::AllegrexContext &ctx, std::uint32_t target) {
    const GuestResult result = call_guest(rt, ctx, target, {}, {});
    ctx.gpr[2] = result.v0;
    ctx.gpr[3] = result.v1;
    ctx.fpr[0] = result.f0;
}
// The same inside a frame of `bytes` (`addiu sp, sp, -bytes; sw ra; jal; ...; jr ra`).
void call_with(psprecomp::Runtime &rt, psprecomp::AllegrexContext &ctx, std::uint32_t target, std::uint32_t bytes) {
    GuestFrame frame(ctx, bytes);
    call_here(rt, ctx, target);
}

// A guest call with the argument registers set like the original sets them before the jal (a0-a3, t0-t3 in order): what the callee
// does not take stays as the caller had it; v0 / v1 / f0 afterwards are the callee's.
std::uint32_t call_set(psprecomp::Runtime &rt, psprecomp::AllegrexContext &ctx, std::uint32_t target, std::initializer_list<std::uint32_t> arguments) {
    unsigned reg = 4u;
    for (const std::uint32_t argument : arguments) {
        if (reg <= 11u) ctx.gpr[reg++] = argument;
    }
    const GuestResult result = call_guest(rt, ctx, target, arguments, {});
    ctx.gpr[2] = result.v0;
    ctx.gpr[3] = result.v1;
    ctx.fpr[0] = result.f0;
    return result.v0;
}

using u32 = std::uint32_t;
using s32 = std::int32_t;
// Where a stream reader keeps its pieces in the 0x30-byte frame: the value the stream writes, the descriptor that carries
// the type tag, and the temporary string (pointer, then -1, then the value's address).
struct StreamSlots {
    u32 value;
    u32 descriptor;
    u32 text;
};
constexpr StreamSlots kByteSlots{1u, 4u, 8u};
constexpr u32 kEmptyRepresentation = 0x08D74FD0u;
// A `std::string` representation shared by every empty string: 0x08B60804 drops a reference at data - 4, 0x08B8542C frees
// the representation at zero or below.
void release_text(psprecomp::Runtime &rt, psprecomp::AllegrexContext &ctx, GuestFrame &frame, u32 data, u32 empty = kEmptyRepresentation,
                  u32 free_function = 0x08B8542Cu) {
    const u32 representation = data - 0xCu;
    if (representation != empty) {
        const s32 remaining = static_cast<s32>(call_set(rt, ctx, 0x08B60804u, {data - 4u, 0xFFFFFFFFu}));
        if (remaining <= 0) call_set(rt, ctx, free_function, {representation, frame.at(0u)});
    }
}
// Reads one value from the stream object a1 into `slots.value` of `frame`: its virtual +8 gets the descriptor (tag `tag`),
// then the temporary string is released and the descriptor reset to the plain-text tag 0x08CCD990.
void read_stream(psprecomp::Runtime &rt, psprecomp::AllegrexContext &ctx, GuestFrame &frame, const StreamSlots &slots, u32 tag) {
    const u32 stream = ctx.gpr[5];
    const u32 descriptor = frame.at(slots.descriptor);
    const u32 vtable = word(rt, stream);
    put(rt, frame.at(slots.text), kEmptyRepresentation + 0xCu);
    put(rt, frame.at(slots.text + 4u), 0xFFFFFFFFu);
    put(rt, frame.at(slots.text + 8u), frame.at(slots.value));
    put(rt, descriptor, tag);
    ctx.gpr[2] = word(rt, vtable + 8u);
    call_set(rt, ctx, ctx.gpr[2], {stream, descriptor, vtable});
    const u32 data = word(rt, frame.at(slots.text));
    ctx.gpr[2] = 0x08CCD990u;
    put(rt, descriptor, 0x08CCD990u);
    release_text(rt, ctx, frame, data);
}
// A flag setter: reads a byte from the stream a1 and replaces bit `bit` of the word at self + offset by its lowest bit.
void set_flag_from_stream(psprecomp::Runtime &rt, psprecomp::AllegrexContext &ctx, u32 offset, unsigned bit) {
    GuestFrame frame(ctx, 0x30u);
    const u32 self = ctx.gpr[4];
    read_stream(rt, ctx, frame, kByteSlots, 0x08CCD9C0u);
    const u32 flags = word(rt, self + offset);
    const u32 value = rt.memory().load8(frame.at(1u));
    ctx.gpr[3] = value;
    ctx.gpr[2] = (flags & ~(1u << bit)) | ((value & 1u) << bit);
    put(rt, self + offset, ctx.gpr[2]);
}

// A byte setter: the stream's byte goes to self + `offset`, and the byte at self + 0xC4 becomes 1.
void store_byte_from_stream(psprecomp::Runtime &rt, psprecomp::AllegrexContext &ctx, u32 offset) {
    GuestFrame frame(ctx, 0x30u);
    const u32 self = ctx.gpr[4];
    read_stream(rt, ctx, frame, kByteSlots, 0x08CCD9C0u);
    ctx.gpr[3] = rt.memory().load8(frame.at(1u));
    ctx.gpr[2] = 1u;
    rt.memory().store8(self + 0xC4u, 1u);
    rt.memory().store8(self + offset, static_cast<std::uint8_t>(ctx.gpr[3]));
}
// `std::string::copy`-like tail call: when `position` is inside the string (size() is the virtual +0xD8) the count is clamped
// as the original does, then 0x08B79A88 (memcpy) continues with the text at self + `text_offset` + position as destination.
void copy_out(psprecomp::Runtime &rt, psprecomp::AllegrexContext &ctx, u32 text_offset) {
    const u32 self = ctx.gpr[4];
    const u32 position = ctx.gpr[5];
    const u32 source = ctx.gpr[6];
    u32 count = ctx.gpr[7];
    {
        GuestFrame frame(ctx, 0x20u);
        const auto size = [&]() {
            const u32 vtable = word(rt, self);
            ctx.gpr[3] = vtable;
            ctx.gpr[2] = word(rt, vtable + 0xD8u);
            return call_set(rt, ctx, ctx.gpr[2], {self});
        };
        const u32 length = size();
        ctx.gpr[2] = position < length ? 1u : 0u;
        if (position >= length) return;
        const u32 remaining = size() - position;
        ctx.gpr[2] = count < remaining ? 1u : 0u;
        if (count < remaining) count = size() - position;
        ctx.gpr[4] = self + text_offset + position;
        ctx.gpr[5] = source;
        ctx.gpr[6] = count;
    }
    jump(ctx, 0x08B79A88u);
}
// Builds two string temporaries from the same range through `build`, looks each one up with `text_of` and combines the two
// results. Nothing happens for a count of zero or less.
void convert_pair(psprecomp::Runtime &rt, psprecomp::AllegrexContext &ctx, u32 build, u32 message, u32 text_of, u32 combine) {
    GuestFrame frame(ctx, 0x30u);
    const u32 second_argument = ctx.gpr[5];
    const u32 count = ctx.gpr[6];
    const u32 third_argument = ctx.gpr[7];
    const u32 first_temporary = frame.at(4u);
    const u32 second_temporary = frame.at(0u);
    if (static_cast<s32>(count) <= 0) return;
    call_set(rt, ctx, build, {first_temporary, second_argument, count, third_argument});
    u32 object = word(rt, first_temporary);
    ctx.gpr[4] = message;
    if (object == 0u) call_set(rt, ctx, 0x08A5BB7Cu, {message});
    const u32 first = call_set(rt, ctx, text_of, {object});
    call_set(rt, ctx, 0x08A5B9ECu, {first_temporary});
    call_set(rt, ctx, build, {second_temporary, third_argument, count, third_argument});
    object = word(rt, second_temporary);
    ctx.gpr[4] = message;
    if (object == 0u) call_set(rt, ctx, 0x08A5BB7Cu, {message});
    const u32 second = call_set(rt, ctx, text_of, {object});
    call_set(rt, ctx, 0x08A5B9ECu, {second_temporary});
    call_set(rt, ctx, combine, {first, second});
}
// Reads a string temporary through the 0x08AB85F0 / 0x08AB856C / 0x08B77BFC chain and, when the object at frame + 0xC holds
// more than nothing, applies `apply` (via 0x088756F0) to a0; the temporary's shared representation is released afterwards.
void apply_text(psprecomp::Runtime &rt, psprecomp::AllegrexContext &ctx, u32 apply) {
    GuestFrame frame(ctx, 0x30u);
    const u32 self = ctx.gpr[4];
    const u32 text = frame.at(4u);
    call_set(rt, ctx, 0x08AB85F0u, {text});
    const u32 first = call_set(rt, ctx, 0x08AB856Cu, {text});
    const u32 converted = call_set(rt, ctx, 0x08B77BFCu, {first});
    const u32 length = call_set(rt, ctx, 0x08AB856Cu, {text});
    ctx.gpr[2] = word(rt, frame.at(0xCu));
    ctx.gpr[4] = self;
    ctx.gpr[5] = 0u;
    ctx.gpr[6] = length;
    if (static_cast<s32>(ctx.gpr[2]) > 0) {
        const u32 value = call_set(rt, ctx, 0x088756F0u, {self, 0u, length});
        call_set(rt, ctx, apply, {self, value, converted});
    }
    const u32 data = word(rt, text);
    ctx.gpr[2] = 0x08D75298u;
    release_text(rt, ctx, frame, data, 0x08D75298u, 0x08B93554u);
}

